MAP
	NAME "SS_MAP_TRAT_TUBERIA_TRATADA_RURAL"
	INCLUDE 'includes/globals.map'
	WEB
		INCLUDE "includes/temp_directory.map"
		METADATA      
			INCLUDE 'includes/common_metadata.map'
		END #METADATA
	END #WEB
	LAYER
        PROJECTION
		 'init=epsg:32614'
		END #PROJECTION
		CONNECTIONTYPE POSTGIS
		NAME "SS_MAP_TRAT_TUBERIA_MEDIDAS_RURAL"
		STATUS DEFAULT
		INCLUDE 'includes/conexion.map'
        DATA "geometry from (select att.gid as gid, att.diametro as diametro, att.geometry as geometry from aguatrat_tub att WHERE att.cl_responsable_mantenimiento=3) as tmp using unique gid using srid=32614"
        PROCESSING "CLOSE_CONNECTION=DEFER"  # Reutiliza conexiones para múltiples consultas
        PROCESSING "POSTGIS_FILTER=YES"      # Filtra geometrías en el lado del servidor
		TYPE line
		MINSCALE 1
		MAXSCALE 150000
		LABELITEM "diametro"
		CLASS
			NAME "tuberia de agua"
			LABEL
				TYPE TRUETYPE
				FONT "arial"
				SIZE 19
				COLOR 0 0 0
			END
		END #CLASS
	END #LAYER
